1	package ociresources
2	
3	import (
4		"fmt"
5		"log"
6	
7		tea "github.com/charmbracelet/bubbletea"
8	
9		"github.com/anthnel/devdesk/internal/config"
10		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
11	)
12	
13	// getSelectedRegistry returns a pointer to the selected registry item, or nil —
14	// including inside a group, where the rows are cached members rather than
15	// config entries and nothing on them is editable.
16	func (m Model) getSelectedRegistry() *config.RegistryItem {
17		idx := m.getSelectedRegistryIndex()
18		if idx < 0 {
19			return nil
20		}
21		return &m.registries[idx]
22	}
23	
24	// enterSelectedGroup drills into the selected group (Rule 111: → goes down a
25	// level). A group with nothing discovered has no level to enter.
26	func (m Model) enterSelectedGroup() (tea.Model, tea.Cmd) {
27		if in := m.registryDrillIn(); !in.Enabled() {
28			return m, m.footer.Warn(in.Reason)
29		}
30		reg := m.getSelectedRegistry()
31		if len(m.groupCache[reg.Slug].Members) == 0 {
32			return m, m.footer.Warn("No members discovered yet — press ctrl+r to look")
33		}
34		m.registryGroupSlug = reg.Slug
35		m.updateRegistryTable()
36		m.registryTable.GotoTop()
37		return m, nil
38	}
39	
40	// leaveGroup goes back up to the registry list (Rule 111: ← and esc).
41	func (m Model) leaveGroup() (tea.Model, tea.Cmd) {
42		if m.registryGroupSlug == "" {
43			return m, nil
44		}
45		m.registryGroupSlug = ""
46		m.updateRegistryTable()
47		m.registryTable.GotoTop()
48		return m, nil
49	}
50	
51	// getSelectedRegistryIndex returns the index of the selected registry, or -1 —
52	// including inside a group, where the rows are cached members and carry no
53	// config index of their own.
54	func (m Model) getSelectedRegistryIndex() int {
55		row, ok := m.registryTable.Selected()
56		if !ok || row.config < 0 || row.config >= len(m.registries) {
57			return -1
58		}
59		return row.config
60	}
61	
62	// editSelectedRegistry opens a registry edit form for the selected entry
63	func (m Model) editSelectedRegistry() (tea.Model, tea.Cmd) {
64		if act := m.registryEntryActions(); !act.Enabled() {
65			return m, m.footer.Warn(act.Reason)
66		}
67		idx := m.getSelectedRegistryIndex()
68		if idx < 0 {
69			return m, m.footer.Warn(reasonNoRegistry)
70		}
71		m.registryForm = NewRegistryEditForm(idx, m.registries[idx], m.registries, m.width-2)
72		return m, nil
