165	// normalizeRepoForRegistry prepends "library/" for bare names on Docker Hub.
166	func normalizeRepoForRegistry(registryURL, repo string) string {
167		if strings.Contains(repo, "/") {
168			return repo
169		}
170		if isDockerHub(registryURL) {
171			return "library/" + repo
172		}
173		return repo
174	}
175	
176	// registryHost strips the scheme from a configured registry URL, leaving what
177	// Docker itself is keyed on: `host[:port]`, plus whatever path a repository
178	// manager serves the registry under.
179	//
180	// A registry URL is written either way in practice — the form does not
181	// normalize it, `registryAPIURL` explicitly accepts both, and this package's own
182	// examples write `https://nexus.example.com/repository/docker-group`. Every
183	// Docker-facing use has to strip it, and none of the three that needed to did
184	// (D39): a `docker pull` reference carrying `https://` is not a reference at
185	// all, and a hub alias compared against a scheme-bearing string never matched,
186	// so images from a Hub configured as `https://docker.io` lost their `library/`
187	// prefix.
188	func registryHost(registryURL string) string {
189		base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
190		for _, scheme := range []string{"https://", "http://"} {
191			if len(base) >= len(scheme) && strings.EqualFold(base[:len(scheme)], scheme) {
192				return base[len(scheme):]
193			}
194		}
195		return base
196	}
197	
198	// isDockerHub reports whether a registry URL names Docker Hub, under either of
199	// the two spellings and with or without a scheme. Hub is the one registry whose
200	// references carry no host, so every caller has to recognise it.
201	func isDockerHub(registryURL string) bool {
202		host := registryHost(registryURL)
203		return strings.EqualFold(host, "docker.io") || strings.EqualFold(host, "registry-1.docker.io")
204	}
